using System.Text.Json;
using Fleet.Orchestrator.Configuration;
using Fleet.Orchestrator.Data;
using Fleet.Orchestrator.Services;
using Fleet.Orchestrator.Tests.Services;

namespace Fleet.Orchestrator.Tests.WorkflowOutcomes;

/// <summary>
/// #476: provisioning writes the <c>WorkflowOutcomes</c> section only for the agent named by
/// <c>FLEET_CTO_AGENT</c>, only when the feature is enabled and the named token has a value in
/// <c>.env</c>. Every other agent's generated bytes — and the coordinator's when disabled — are
/// unchanged, and no grant, MCP tool or ACL moves with it.
/// </summary>
public sealed class ProvisioningWorkflowOutcomeTests
{
    private const string Suite = "WorkflowOutcomeSuite";
    private const string TokenKey = "FLEET_WORKFLOW_OUTCOMES_COORDINATOR_TOKEN";
    private const string TokenValue = "scoped-token-placeholder";
    private const string BaseUrl = "http://fleet-orchestrator:5000";

    private static Dictionary<string, string?> Feature(bool enabled = true, string tokenKey = TokenKey, long generation = 3) => new()
    {
        ["WorkflowOutcomes:Enabled"] = enabled ? "true" : "false",
        ["WorkflowOutcomes:CoordinatorTokenKey"] = tokenKey,
        ["WorkflowOutcomes:CoordinatorBaseUrl"] = BaseUrl,
        ["WorkflowOutcomes:CoordinatorGeneration"] = generation.ToString(System.Globalization.CultureInfo.InvariantCulture),
    };

    /// <summary>Provisions <paramref name="name"/> and returns its generated appsettings, settings and mcp files.</summary>
    private static async Task<(string Appsettings, string Settings, string Mcp, IReadOnlyList<string> Logs)> ProvisionAsync(
        string name, Dictionary<string, string?>? config, string? envExtra = null)
    {
        await using var h = ProvisioningHarness.Create(config);
        if (envExtra is not null) File.AppendAllText(Path.Combine(h.BaseDir, ".env"), envExtra);
        await h.SeedAsync(db =>
        {
            var agent = new Agent
            {
                Name = name, DisplayName = name, Role = "co-cto", Model = "claude-opus-5-5", Provider = "claude",
                ContainerName = "fleet-" + name, MemoryLimitMb = 1024, ShortName = name.Replace("-", ""),
                WorkDir = "/workspace",
            };
            agent.Tools.Add(new AgentTool { ToolName = "Read", IsEnabled = true });
            agent.McpEndpoints.Add(new AgentMcpEndpoint
            {
                McpName = "fleet-temporal", Url = "http://fleet-temporal-bridge:3001/mcp", TransportType = "http",
            });
            db.Agents.Add(agent);
        });
        var result = await h.Service.ProvisionAsync(name);
        Assert.True(result.Success, result.Message);
        var dir = h.GeneratedDir("fleet-" + name);
        return (await File.ReadAllTextAsync(Path.Combine(dir, "appsettings.json")),
            await File.ReadAllTextAsync(Path.Combine(dir, "settings.json")),
            await File.ReadAllTextAsync(Path.Combine(dir, ".mcp.json")),
            h.Logs.Entries.Select(e => e.Message).ToList());
    }

    private static Agent AgentNamed(string name) => new()
    {
        Name = name, DisplayName = name, ContainerName = "fleet-" + name, Role = "developer", Model = "claude-opus-5-5",
        Provider = "claude",
    };

    private static string Env(string value = TokenValue) => $"{TokenKey}={value}\n";

    [Fact]
    [Trait(Suite, "coordinator")]
    public async Task Coordinator_FeatureOnAndTokenPresent_GetsExactlyTheSection()
    {
        var (appsettings, _, _, logs) = await ProvisionAsync(ProvisioningHarness.CtoAgent, Feature(), Env());

        using var doc = JsonDocument.Parse(appsettings);
        var section = doc.RootElement.GetProperty("WorkflowOutcomes");
        Assert.True(section.GetProperty("Enabled").GetBoolean());
        Assert.Equal(BaseUrl, section.GetProperty("BaseUrl").GetString());
        Assert.Equal(TokenValue, section.GetProperty("ScopedToken").GetString());
        Assert.Equal(ProvisioningHarness.CtoAgent, section.GetProperty("Coordinator").GetString());
        Assert.Equal(3, section.GetProperty("CoordinatorGeneration").GetInt64());
        Assert.Equal(30, section.GetProperty("PollSeconds").GetInt32());
        Assert.Equal("/workspace/.fleet/workflow-outcome-inbox.json", section.GetProperty("InboxPath").GetString());
        Assert.Equal(["Enabled", "BaseUrl", "ScopedToken", "Coordinator", "CoordinatorGeneration", "PollSeconds", "InboxPath"],
            section.EnumerateObject().Select(p => p.Name).ToArray());
        Assert.DoesNotContain(logs, l => l.Contains(TokenValue, StringComparison.Ordinal));
    }

    [Fact]
    [Trait(Suite, "coordinator")]
    public async Task Coordinator_FeatureOn_ChangesNothingElseInAnyGeneratedFile()
    {
        var off = await ProvisionAsync(ProvisioningHarness.CtoAgent, null, Env());
        var on = await ProvisionAsync(ProvisioningHarness.CtoAgent, Feature(), Env());

        var withoutSection = JsonDocument.Parse(on.Appsettings).RootElement.EnumerateObject()
            .Where(p => p.Name != "WorkflowOutcomes").ToDictionary(p => p.Name, p => p.Value.GetRawText());
        var baseline = JsonDocument.Parse(off.Appsettings).RootElement.EnumerateObject()
            .ToDictionary(p => p.Name, p => p.Value.GetRawText());
        Assert.Equal(baseline, withoutSection);
        Assert.Equal(off.Settings, on.Settings);
        Assert.Equal(off.Mcp, on.Mcp);
    }

    [Fact]
    [Trait(Suite, "coordinator")]
    public async Task OtherAgent_FeatureOn_IsByteIdenticalToFeatureOff()
    {
        var off = await ProvisionAsync("agent1", null, Env());
        var on = await ProvisionAsync("agent1", Feature(), Env());

        Assert.Equal(off.Appsettings, on.Appsettings);
        Assert.Equal(off.Settings, on.Settings);
        Assert.Equal(off.Mcp, on.Mcp);
        Assert.DoesNotContain("WorkflowOutcomes", on.Appsettings, StringComparison.Ordinal);
        Assert.DoesNotContain(TokenValue, on.Appsettings, StringComparison.Ordinal);
    }

    public static TheoryData<string> NotEmitted =>
        ["disabled", "token-missing", "token-blank", "admin-token-key", "config-token-key", "case-mismatched-name"];

    [Theory]
    [Trait(Suite, "coordinator")]
    [MemberData(nameof(NotEmitted))]
    public async Task Coordinator_WithoutEveryPrecondition_IsByteIdenticalToFeatureOff(string variant)
    {
        var name = variant == "case-mismatched-name" ? ProvisioningHarness.CtoAgent.ToUpperInvariant() : ProvisioningHarness.CtoAgent;
        var (config, env) = variant switch
        {
            "disabled" => (Feature(enabled: false), Env()),
            "token-missing" => (Feature(), ""),
            "token-blank" => (Feature(), $"{TokenKey}=\n"),
            "admin-token-key" => (Feature(tokenKey: "ORCHESTRATOR_AUTH_TOKEN"), "ORCHESTRATOR_AUTH_TOKEN=admin-placeholder\n"),
            "config-token-key" => (Feature(tokenKey: "orchestrator__configtoken"), "orchestrator__configtoken=config-placeholder\n"),
            "case-mismatched-name" => (Feature(), Env()),
            _ => throw new ArgumentOutOfRangeException(nameof(variant)),
        };

        var baseline = await ProvisionAsync(name, null, env);
        var actual = await ProvisionAsync(name, config, env);

        Assert.Equal(baseline.Appsettings, actual.Appsettings);
        Assert.DoesNotContain("WorkflowOutcomes", actual.Appsettings, StringComparison.Ordinal);
        Assert.DoesNotContain("admin-placeholder", actual.Appsettings, StringComparison.Ordinal);
        Assert.DoesNotContain("config-placeholder", actual.Appsettings, StringComparison.Ordinal);
        Assert.All(actual.Logs, l => Assert.DoesNotContain("placeholder", l, StringComparison.Ordinal));
    }

    [Fact]
    [Trait(Suite, "coordinator")]
    public void Build_NamesOnlyTheExactCoordinatorAndReadsTheNamedEnvValue()
    {
        var options = new WorkflowOutcomeOptions
        {
            Enabled = true, CoordinatorTokenKey = TokenKey, CoordinatorBaseUrl = BaseUrl, CoordinatorGeneration = 2,
        };
        var env = new Dictionary<string, string> { [TokenKey] = TokenValue };
        var coordinator = AgentNamed("coordinator");
        coordinator.WorkDir = "/srv/work/";

        var built = ContainerProvisioningService.BuildWorkflowOutcomeProvisioning(coordinator, "coordinator", options, env);

        Assert.Equal(new WorkflowOutcomeProvisioning(BaseUrl, TokenValue, "coordinator", 2, 30,
            "/srv/work/.fleet/workflow-outcome-inbox.json"), built);
        Assert.Null(ContainerProvisioningService.BuildWorkflowOutcomeProvisioning(AgentNamed("agent1"), "coordinator", options, env));
        Assert.Null(ContainerProvisioningService.BuildWorkflowOutcomeProvisioning(coordinator, "", options, env));
        Assert.Null(ContainerProvisioningService.BuildWorkflowOutcomeProvisioning(coordinator, null, options, env));
    }

    [Fact]
    [Trait(Suite, "coordinator")]
    public void GenerateAppsettingsJson_WithoutTheSection_IsTheExistingOutput()
    {
        var agent = AgentNamed("agent1");

        Assert.Equal(ContainerProvisioningService.GenerateAppsettingsJson(agent, "coordinator"),
            ContainerProvisioningService.GenerateAppsettingsJson(agent, "coordinator", workflowOutcomes: null));
    }
}
